/*
 * prog59_rule110.c
 *
 * The original binary implements a small command‑line utility that
 * simulates elementary cellular automaton Rule 110.
 *
 * Usage:
 *     prog59_rule110 <binary‑string> <steps>
 *
 * <binary‑string> must be a non‑empty string consisting only of the
 * characters ‘0’ and ‘1’.  <steps> is a decimal integer (0 ≤ steps ≤ 200)
 * that specifies how many rows of the automaton to print, including the
 * initial row.
 *
 * If the arguments are missing, malformed or the string contains any
 * character other than ‘0’ or ‘1’, the program prints the single line
 * "INVALID_INPUT" and exits with status 1.
 *
 * Otherwise the program prints <steps> rows, each terminated by a
 * newline.  The first row is the input string; each subsequent row is
 * obtained from the previous one using Rule 110 with fixed‑zero
 * boundary conditions.
 *
 * The implementation below follows the logic observed in the decompiled
 * state‑machine of the original binary, but is written in clear, idiomatic
 * C.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_STEPS 200

/* Rule 110 lookup table.
 * Index = left*4 + centre*2 + right   (binary pattern 111..000)
 * Value = new state (0 or 1)
 */
static const int RULE110[8] = {
    0, /* 000 */
    1, /* 001 */
    1, /* 010 */
    1, /* 011 */
    0, /* 100 */
    1, /* 101 */
    1, /* 110 */
    0  /* 111 */
};

/* Print the error message used by the original program and exit. */
static void invalid_input(void) {
    puts("INVALID_INPUT");
    exit(1);
}

/* Verify that a string consists only of ‘0’ and ‘1’. */
static void check_binary_string(const char *s) {
    for (size_t i = 0; s[i] != '\0'; ++i) {
        if (s[i] != '0' && s[i] != '1')
            invalid_input();
    }
}

/* Compute the next generation of a Rule‑110 automaton.
 * The result is written into `next` (which must have room for `len` chars
 * plus a terminating NUL).  Boundary cells assume a neighbour value of 0.
 */
static void next_row_rule110(const char *cur, char *next, size_t len) {
    for (size_t i = 0; i < len; ++i) {
        int left   = (i == 0)     ? 0 : cur[i - 1] - '0';
        int centre = cur[i]      - '0';
        int right  = (i + 1 == len) ? 0 : cur[i + 1] - '0';
        int idx = (left << 2) | (centre << 1) | right;
        next[i] = (char)(RULE110[idx] + '0');
    }
    next[len] = '\0';
}

int main(int argc, char **argv) {
    /* ----- argument validation ----- */
    if (argc < 3)
        invalid_input();

    const char *init = argv[1];
    size_t len = strlen(init);
    if (len == 0)
        invalid_input();

    check_binary_string(init);

    char *endptr;
    long steps = strtol(argv[2], &endptr, 10);
    if (endptr == argv[2] || *endptr != '\0')
        invalid_input();
    if (steps < 0)
        invalid_input();
    if (steps > MAX_STEPS)
        steps = MAX_STEPS;

    /* ----- simulation ----- */
    /* Allocate two buffers to hold the current and next rows. */
    char *row_cur  = malloc(len + 1);
    char *row_next = malloc(len + 1);
    if (!row_cur || !row_next) {
        perror("malloc");
        return 1;
    }
    memcpy(row_cur, init, len + 1);   /* include terminating NUL */

    for (long printed = 0; printed < steps; ++printed) {
        /* Print the current row */
        for (size_t i = 0; i < len; ++i)
            putchar(row_cur[i]);
        putchar('\n');

        /* Compute the next row (unless this is the last iteration) */
        if (printed + 1 < steps)
            next_row_rule110(row_cur, row_next, len);

        /* Swap buffers */
        char *tmp = row_cur;
        row_cur = row_next;
        row_next = tmp;
    }

    free(row_cur);
    free(row_next);
    return 0;
}
